// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Uluslararası ödüller, evrensel kodlamalar ve işaret sistemleri (Nobel, Pritzker, Fields, Pulitzer, Mors, Braille, NATO fonetik alfabesi, ISO kodları) (kolay).
const ozCulture17Kolay = <(String, String, List<String>, String)>[
  ('Alfred Nobel\'in 1895 yılında Paris\'te imzaladığı vasiyetnamesinde yer alan beş özgün ödül kategorisi arasında aşağıdakilerden hangisi bulunmaz?', 'Ekonomi Bilimleri', ['Fizyoloji veya Tıp', 'Edebiyat', 'Fizik'], 'Ekonomi ödülü Alfred Nobel\'in 1895 tarihli vasiyetinde yer almamış, 1968 yılında İsveç Merkez Bankası tarafından onun anısına ihdas edilmiştir.'),
  ('Nobel Ödülleri her yıl geleneksel olarak 10 Aralık\'ta düzenlenen törenlerle sahiplerine takdim edilir; bu tarihin seçilme nedeni nedir?', 'Alfred Nobel\'in ölüm yıl dönümü olması', ['Alfred Nobel\'in doğum yıl dönümü olması', 'İlk vasiyetnamenin Paris\'te imzalandığı gün olması', 'İsveç Kraliyet Bilimler Akademisinin kuruluş günü olması'], 'Alfred Nobel 10 Aralık 1896 tarihinde İtalya\'nın Sanremo kentinde hayatını kaybettiği için ödül törenleri bu tarihte yapılır.'),
  ('Diğer Nobel ödülleri İsveç\'in başkenti Stockholm\'de verilirken, Nobel Barış Ödülü hangi ülkenin başkentinde takdim edilmektedir?', 'Norveç - Oslo', ['Danimarka - Kopenhag', 'Finlandiya - Helsinki', 'İsviçre - Cenevre'], 'Alfred Nobel\'in vasiyeti doğrultusunda Nobel Barış Ödülü Norveç Parlamentosunun seçtiği komite tarafından Oslo\'da verilir.'),
  ('Alfred Nobel\'e servetinin büyük bölümünü kazandıran ve 1867 yılında patentini aldığı en ünlü buluşu aşağıdakilerden hangisidir?', 'Dinamit', ['Dumansız barut', 'Buhar türbini', 'Telgraf makinesi'], 'Sıvı nitrogliserini kieselguhr adlı gözenekli toprakla karıştırarak güvenli hale getiren Alfred Nobel, 1867\'de dinamitin patentini almıştır.'),
  ('İlk Nobel Ödülleri hangi yılda sahiplerine verilmeye başlanmıştır?', '1901', ['1896', '1905', '1910'], 'Alfred Nobel\'in ölümünden beş yıl sonra, vakfın tüzüğü ve komitelerin oluşturulması tamamlanarak ilk ödüller 1901 yılında verilmiştir.'),
  ('2006 yılında Nobel Edebiyat Ödülü\'nü kazanarak bu ödülü alan ilk Türk yazar olan edebiyatçımız kimdir?', 'Orhan Pamuk', ['Yaşar Kemal', 'Nazım Hikmet Ran', 'Ahmet Hamdi Tanpınar'], 'Orhan Pamuk, kentinin melankolik ruhunun izlerini sürerken kültürlerin çatışması ve örülmesi için yeni simgeler bulduğu gerekçesiyle 2006 Nobel Edebiyat Ödülü\'nü almıştır.'),
  ('Hasar gören DNA\'nın hücreler tarafından nasıl onarıldığını haritalandıran çalışmalarıyla 2015 Nobel Kimya Ödülü\'nü kazanan Türk bilim insanı kimdir?', 'Aziz Sancar', ['Oktay Sinanoğlu', 'Feza Gürsey', 'Cahit Arf'], 'Aziz Sancar, nükleotid kesip çıkarma onarımı mekanizmasını aydınlatan araştırmalarıyla Tomas Lindahl ve Paul Modrich ile birlikte 2015 Nobel Kimya Ödülü\'nü kazanmıştır.'),
  ('Kamuoyunda sıklıkla "Matematiğin Nobel\'i" olarak anılan ve dört yılda bir düzenlenen Uluslararası Matematikçiler Kongresi\'nde (ICM) verilen prestijli ödül hangisidir?', 'Fields Madalyası', ['Turing Ödülü', 'Pritzker Ödülü', 'Pulitzer Ödülü'], 'Kanadalı matematikçi John Charles Fields\'ın girişimi ve mirasıyla kurulan Fields Madalyası, matematik dünyasının en saygın ödüllerinden biridir.'),
  ('Fields Madalyası kaç yılda bir düzenlenen Uluslararası Matematikçiler Kongresi sırasında sahiplerine takdim edilir?', 'Dört yılda bir', ['Her yıl', 'İki yılda bir', 'Beş yılda bir'], 'Fields Madalyası, Uluslararası Matematik Birliği (IMU) tarafından dört yılda bir toplanan Uluslararası Matematikçiler Kongresi\'nin açılış töreninde verilir.'),
  ('Matematik alanında Nobel Ödülü\'nün bıraktığı boşluğu doldurmak üzere Norveç Hükümeti tarafından kurulan ve 2003 yılından itibaren her yıl verilen uluslararası ödül hangisidir?', 'Abel Ödülü', ['Gauss Madalyası', 'Wolf Ödülü', 'Chern Madalyası'], '19. yüzyılın dahi Norveçli matematikçisi Niels Henrik Abel\'in 200. doğum yılı vesilesiyle kurulan Abel Ödülü, her yıl Oslo\'da verilmektedir.'),
  ('Kamuoyunda "Bilgisayar Biliminin Nobel\'i" olarak kabul edilen ve 1966 yılından beri her yıl verilen en saygın bilişim ödülü hangisidir?', 'Turing Ödülü', ['Fields Madalyası', 'Pritzker Ödülü', 'Booker Ödülü'], 'Bilgisayar biliminin kuramsal kurucusu Alan Turing\'in adını taşıyan A. M. Turing Ödülü, bilişim dünyasının en yüksek onurudur.'),
  ('Turing Ödülü\'ne adını veren İngiliz matematikçi ve mantıkçı Alan Mathison Turing, İkinci Dünya Savaşı sırasında Bletchley Park\'ta hangi şifreleme makinesinin kodlarının kırılmasında başrol oynamıştır?', 'Enigma', ['Lorenz', 'Hagelin', 'Purple'], 'Alan Turing, Alman ordusunun kullandığı Enigma şifreleme makinesinin mesajlarını çözmek için elektromekanik "Bombe" makinelerini geliştirerek savaşın seyrini değiştirmiştir.'),
  ('Yaşayan bir mimara yapılı çevreye ve insanlığa mimarlık sanatı aracılığıyla yaptığı tutarlı katkılar nedeniyle her yıl verilen ve "Mimarlığın Nobel\'i" olarak bilinen ödül hangisidir?', 'Pritzker Mimarlık Ödülü', ['Ağa Han Mimarlık Ödülü', 'Stirling Mimarlık Ödülü', 'Mies van der Rohe Ödülü'], '1979 yılında kurulan Pritzker Mimarlık Ödülü, dünya çapında mimarlık mesleğinin en prestijli bireysel ödülü kabul edilir.'),
  ('2004 yılında Pritzker Mimarlık Ödülü\'nü kazanarak bu ödülü alan tarihteki ilk kadın ve aynı zamanda ilk Irak doğumlu mimar kimdir?', 'Zaha Hadid', ['Kazuyo Sejima', 'Carme Pigem', 'Yvonne Farrell'], 'Akışkan, kıvrımlı ve dekonstrüktivist formlarıyla "eğrilerin kraliçesi" olarak anılan Irak asıllı İngiliz mimar Zaha Hadid, 2004\'te Pritzker kazanan ilk kadın olmuştur.'),
  ('Gazetecilik, edebiyat ve müzik besteciliği alanlarındaki üstün başarıları ödüllendirmek amacıyla 1917 yılından bu yana Amerika Birleşik Devletleri\'nde her yıl verilen prestijli ödül hangisidir?', 'Pulitzer Ödülü', ['Booker Ödülü', 'Goncourt Ödülü', 'Cervantes Ödülü'], 'Macar asıllı Amerikalı gazete yayıncısı Joseph Pulitzer\'in vasiyeti üzerine 1917\'den beri verilen Pulitzer Ödülleri, özellikle gazetecilik ve Amerikan edebiyatında en saygın ölçüttür.'),
  ('1969 yılında Birleşik Krallık\'ta kurulan ve İngilizce yazılmış, Birleşik Krallık veya İrlanda\'da yayımlanmış en iyi özgün uzun kurgu eserine her yıl verilen prestijli edebiyat ödülü hangisidir?', 'Booker Ödülü', ['Pulitzer Ödülü', 'Goncourt Ödülü', 'Hugo Ödülü'], 'Başlangıçta Booker-McConnell gıda şirketinin kurduğu ve uzun yıllar "Man Booker Ödülü" adıyla da anılan Booker Ödülü, İngilizce edebiyat dünyasının en etkili roman ödülüdür.'),
  ('Edebiyat ödülleri dünyasında "kısa liste" (shortlist) öncesinde açıklanan ve genellikle 12-13 aday kitaptan oluşan ilk eleme listesine verilen yaygın ad nedir?', 'Uzun liste (Longlist)', ['Onur listesi (Honor roll)', 'Yedek liste (Waitlist)', 'Veto listesi (Blacklist)'], 'Özellikle Booker Ödülleri\'nde "Booker Dozen" (Booker Düzinesi) olarak da bilinen 12-13 kitaplık uzun liste (longlist) önce açıklanır, ardından içinden 6 kitaplık kısa liste (shortlist) seçilir.'),
  ('Uluslararası Standartlar Teşkilatı (ISO) 3166-1 alpha-2 standardına göre Türkiye\'nin iki harfli ülke kodu hangisidir?', 'TR', ['TK', 'TU', 'TY'], 'ISO 3166-1 alpha-2 standardında Türkiye TR, alpha-3 standardında ise TUR koduyla temsil edilir.'),
  ('ISO 4217 uluslararası para birimi standardına göre Türk lirasının üç harfli resmi kodu hangisidir?', 'TRY', ['TRL', 'TLI', 'TUL'], '2005 yılındaki para reformu sonrasında Türk lirasının ISO 4217 kodu TRL yerine TRY olarak tescil edilmiştir.'),
  ('Avrupa Birliği\'nin ortak para birimi olan avronun ISO 4217 standardındaki üç harfli kodu hangisidir?', 'EUR', ['EUO', 'ERO', 'EUC'], 'ISO 4217 standardında avro için EUR kodu, sembol olarak ise € işareti kullanılır.'),
  ('Japonya\'nın para birimi olan yenin ISO 4217 standardındaki üç harfli kodu hangisidir?', 'JPY', ['JAP', 'JYN', 'JPE'], 'Japonya\'nın ülke kodu JP ile para birimi Yen\'in baş harfi birleştirilerek JPY kodu oluşturulmuştur.'),
  ('ISO 639-1 uluslararası dil kodları standardına göre Türkçenin iki harfli dil kodu hangisidir?', 'tr', ['tu', 'tk', 'tc'], 'ISO 639-1 standardında diller küçük iki harfle gösterilir; Türkçenin kodu tr, üç harfli ISO 639-2 kodu ise tur\'dur.'),
  ('Dünya saat dilimlerinin referans noktası kabul edilen Eşgüdümlü Evrensel Zaman\'ın uluslararası kısaltması nedir?', 'UTC', ['GMT', 'CET', 'EST'], 'Eşgüdümlü Evrensel Zaman için İngilizce (CUT) ve Fransızca (TUC) kısaltmalar arasında uzlaşı sağlanarak UTC kısaltması benimsenmiştir.'),
  ('Başlangıç meridyeni (0° boylamı) olarak kabul edilen ve saat dilimlerine tarihsel temel oluşturan gözlemevi Londra\'nın hangi semtinde yer alır?', 'Greenwich', ['Westminster', 'Kensington', 'Wimbledon'], '1884 Uluslararası Meridyen Konferansı ile Londra\'daki Greenwich Kraliyet Gözlemevi\'nden geçen meridyen 0° başlangıç boylamı seçilmiştir.'),
  ('Günlük hayatta ve ofislerde en yaygın kullanılan standart A4 kâğıdının milimetre cinsinden tam boyutları nedir?', '210 × 297 mm', ['200 × 300 mm', '215 × 280 mm', '220 × 310 mm'], 'ISO 216 standardına göre A4 boyutundaki bir kâğıt 210 mm genişliğe ve 297 mm uzunluğa sahiptir.'),
  ('Bir A0 kâğıt tabakası her seferinde uzun kenarından tam ortadan ikiye kesilerek bölündüğünde toplam kaç adet A4 kâğıdı elde edilir?', '16 adet', ['8 adet', '4 adet', '32 adet'], 'Her basamakta kâğıt sayısı ikiye katlanır: A0 = 2 A1 = 4 A2 = 8 A3 = 16 A4.'),
  ('İki adet A4 kâğıdı uzun kenarları boyunca yan yana birleştirildiğinde hangi kâğıt boyutu elde edilir?', 'A3', ['A5', 'A2', 'B4'], 'A serisinde numara küçüldükçe boyut büyür; iki adet A4 (210×297 mm) birleştiğinde bir adet A3 (297×420 mm) oluşturur.'),
  ('Bir A4 kâğıdı uzun kenarından tam ortadan ikiye katlandığında oluşan her bir yaprağın standart boyutu nedir?', 'A5', ['A3', 'A6', 'C4'], 'A4 kâğıdının yarısı bir alt boy olan A5 (148 × 210 mm) boyutunu verir; not defterlerinde ve kitaplarda sıkça kullanılır.'),
  ('Kitapların arka kapağında yer alan ve yayınları küresel ölçekte tekil olarak tanımlayan "ISBN" kısaltmasının Türkçe karşılığı nedir?', 'Uluslararası Standart Kitap Numarası', ['Uluslararası Süreli Basım Numarası', 'Uluslararası Sayısal Barkod Normu', 'Uluslararası Sınıflandırma Belge No'], 'ISBN (International Standard Book Number), ISO 2108 standardıyla düzenlenen uluslararası kitap tanımlama numarasıdır.'),
  ('Kurum ve işletmelerde "Kalite Yönetim Sistemi" şartlarını belirleyen ve dünyada en yaygın belgelendirilen ISO standardı hangisidir?', 'ISO 9001', ['ISO 14001', 'ISO 27001', 'ISO 45001'], 'ISO 9001, ürün ve hizmet kalitesini güvence altına alan süreç odaklı Kalite Yönetim Sistemi standardıdır.'),
  ('Akıllı telefon ve elektronik cihazların özelliklerinde sıkça belirtilen "IP68" kodundaki "IP" harflerinin İngilizce açılımı ve anlamı nedir?', 'Ingress Protection (Giriş / Sızdırmazlık Koruması)', ['Internal Pressure (İç Basınç Dayanımı)', 'Internet Protocol (İnternet İletişim Protokolü)', 'Impact Proofing (Darbe Sönümleme Sınıfı)'], 'IEC 60529 standardında tanımlanan IP kodu (Ingress Protection), elektrikli muhafazaların katı cisimlere ve sıvı girişine karşı koruma derecesini belirtir.'),
  ('"IP68" koruma sınıfı kodundaki iki rakam sırasıyla hangi dış etkenlere karşı koruma düzeyini gösterir?', 'İlk rakam katı cisim ve toza, ikinci rakam suya karşı korumayı', ['İlk rakam suya, ikinci rakam yüksek sıcaklığa karşı korumayı', 'İlk rakam düşme darbesine, ikinci rakam toza karşı korumayı', 'İlk rakam elektrik kaçağına, ikinci rakam neme karşı korumayı'], 'IEC 60529 standardında IP harflerinden sonraki birinci basamak (0-6) katı yabancı cisim/toz korumasını, ikinci basamak (0-9K) sıvı/su korumasını ifade eder.'),
  ('Denizcilikte ve meteorolojide rüzgârın şiddetini deniz ve kara üzerindeki gözlemlenen etkilerine göre derecelendiren ölçeğin adı nedir?', 'Beaufort (Bofor) ölçeği', ['Richter (Rihter) ölçeği', 'Mohs sertlik ölçeği', 'Fujita hortum ölçeği'], '1805 yılında İrlandalı Tuğamiral Sir Francis Beaufort tarafından geliştirilen Beaufort ölçeği, rüzgâr şiddetini gözlemsel etkilerle sınıflandırır.'),
  ('Klasik uluslararası Beaufort rüzgâr ölçeği hangi sayısal aralıkta derecelendirilir?', '0 ile 12 arasında', ['1 ile 10 arasında', '0 ile 100 arasında', '1 ile 5 arasında'], 'Standart Beaufort ölçeği 0 (Sakin / Limanlık) seviyesinden başlar ve 12 (Kasırga / Tayfun) seviyesine kadar 13 basamaktan oluşur.'),
  ('Beaufort ölçeğinin en üst basamağı olan "12" kuvvetindeki rüzgâr (64 knot / 118 km/sa ve üzeri) hangi adla tanımlanır?', 'Kasırga', ['Fırtınamsı rüzgâr', 'Kuvvetli meltem', 'Sert esinti'], 'Beaufort 12 seviyesi rüzgâr hızının 64 knot (118 km/sa) ve üzerine çıktığı yıkıcı kasırga/orkan koşullarını ifade eder.'),
  ('Minerallerin birbirini çizebilme direncine dayanan "Mohs sertlik ölçeği" hangi sayılar arasında derecelendirilir?', '1 ile 10 arasında', ['0 ile 100 arasında', '1 ile 5 arasında', '0 ile 14 arasında'], 'Alman mineralog Friedrich Mohs\'un 1812\'de oluşturduğu ölçek, en yumuşak mineral 1 ve en sert doğal mineral 10 olacak şekilde 10 referans mineralden oluşur.'),
  ('Mohs sertlik ölçeğinde "10" numarayla en üst sırada yer alan en sert doğal mineral hangisidir?', 'Elmas', ['Kuvars', 'Yakut', 'Topaz'], 'Saf karbondan oluşan kristal yapısıyla elmas, Mohs ölçeğinde 10 değerine sahip referans mineraldir.'),
  ('Mohs sertlik ölçeğinde "1" numarayla en alt sırada yer alan ve tırnakla bile kolayca çizilebilen en yumuşak mineral hangisidir?', 'Talk', ['Alçıtaşı', 'Kalsit', 'Florit'], 'Magnezyum silikat yapısındaki talk (pudra taşı), Mohs sertlik ölçeğinin 1 numaralı en yumuşak referans mineralidir.'),
  ('Binalarda ve kamusal alanlarda "Acil Çıkış" (Emergency Exit) yönlendirme levhaları ISO 7010 standardına göre hangi zemin rengine ve piktogram rengine sahiptir?', 'Yeşil zemin üzerine beyaz piktogram', ['Kırmızı zemin üzerine siyah piktogram', 'Sarı zemin üzerine siyah piktogram', 'Mavi zemin üzerine sarı piktogram'], 'ISO 3864 ve ISO 7010 güvenlik renkleri standardında "yeşil" renk güvenli durumu, ilk yardımı ve acil kaçış yollarını beyaz figürle gösterir.'),
  ('ISO 7010 standardında yangın söndürme tüpü, yangın hortumu ve yangın alarm butonu gibi yangın güvenliği ekipmanlarının yerini gösteren levhalar hangi şekil ve renktedir?', 'Kırmızı kare/dikdörtgen zemin üzerine beyaz piktogram', ['Yeşil daire zemin üzerine siyah piktogram', 'Mavi üçgen zemin üzerine sarı piktogram', 'Sarı daire zemin üzerine kırmızı piktogram'], 'Yangınla mücadele ekipmanlarının hızlı fark edilmesi için kırmızı kare/dikdörtgen zemin ve beyaz alev eşlikli beyaz ekipman sembolü kullanılır.'),
  ('Karayollarında tehlikeli madde taşıyan tankerlerin arkasındaki turuncu dikdörtgen plakaların tabi olduğu Avrupa anlaşmasının uluslararası kısaltması nedir?', 'ADR', ['TIR', 'CMR', 'IATA'], 'Tehlikeli Malların Karayolu ile Uluslararası Taşımacılığına İlişkin Avrupa Anlaşması, Fransızca baş harflerinden oluşan ADR koduyla anılır.'),
  ('Denizde, havada ve karada radyo-telsiz veya Mors alfabesiyle gönderilen evrensel imdat çağrısı "SOS", Mors kodunda hangi dizilimle iletilir?', 'Üç kısa, üç uzun, üç kısa sinyal (· · · — — — · · ·)', ['Üç uzun, üç kısa, üç uzun sinyal (— — — · · · — — —)', 'İki kısa, iki uzun, iki kısa sinyal (· · — — · ·)', 'Dört kısa, bir uzun, dört kısa sinyal (· · · · — · · · ·)'], '1906 Uluslararası Radyotelgraf Konferansı\'nda kabul edilen SOS sinyali, gönderimi ve ayırt edilmesi çok kolay olduğu için 3 nokta, 3 çizgi, 3 nokta diziliminden seçilmiştir.'),
  ('Yangın söndürücü tüplerin üzerindeki harf sınıflandırmasında (EN 2 standardı) "A sınıfı" yangınlar hangi tür maddelerin yanmasını ifade eder?', 'Odun, kâğıt, kumaş gibi kor bırakan katı maddelerin yangınlarını', ['Benzin, mazot, tiner ve yağ gibi yanıcı sıvıların yangınlarını', 'Doğalgaz, LPG, bütan ve propan gibi yanıcı gazların yangınlarını', 'Magnezyum, titanyum ve sodyum gibi yanıcı metallerin yangınlarını'], 'Avrupa EN 2 yangın sınıflandırmasında A katı maddeleri, B yanıcı sıvıları, C yanıcı gazları, D yanıcı metalleri, F ise pişirme yağlarını temsil eder.'),
  ('Elektromanyetik telgraf üzerinden nokta ve çizgi sinyalleriyle iletişim kurmayı sağlayan alfabeyi Alfred Vail ile birlikte geliştiren Amerikalı mucit ve ressam kimdir?', 'Samuel Morse', ['Alexander Graham Bell', 'Guglielmo Marconi', 'Thomas Alva Edison'], 'Samuel Morse ve yardımcısı Alfred Vail, 1830\'lu yıllarda elektrikli telgraf sistemiyle uyumlu Mors kodunu geliştirmiştir.'),
  ('Uluslararası Mors alfabesinde tehlike ve acil yardım çağrısı olarak kullanılan "SOS" sinyalinin nokta ve çizgi dizilimi nasıldır?', 'Üç nokta, üç çizgi, üç nokta', ['Üç çizgi, üç nokta, üç çizgi', 'İki nokta, iki çizgi, iki nokta', 'Bir nokta, üç çizgi, bir nokta'], 'Uluslararası Mors kodunda S harfi üç nokta (...), O harfi üç çizgi (---) ile gösterilir ve SOS ara verilmeden "...---..." şeklinde gönderilir.'),
  ('Uluslararası Mors alfabesinde yalnızca tek bir nokta (.) ile temsil edilen harf hangisidir?', 'E', ['A', 'T', 'İ'], 'İngilizcede en sık kullanılan harf olan E harfi, iletişim hızını artırmak amacıyla tek nokta ile kodlanmıştır.'),
  ('Uluslararası Mors alfabesinde yalnızca tek bir çizgi (-) ile gösterilen harf hangisidir?', 'T', ['M', 'O', 'N'], 'Sık kullanılan harflere kısa kodlar verilmesi ilkesi doğrultusunda T harfi tek bir çizgi ile temsil edilir.'),
  ('Mors alfabesi yalnızca sesli telgraf sinyalleriyle değil, görüş mesafesindeki gemiler arasında hangi görsel araçla da yaygın olarak iletilir?', 'Aldis lambası', ['Semafor el bayrakları çifti', 'Uluslararası kod flamaları dizisi', 'Deniz radarı yansıtıcı küresi'], 'Panjurlu bir projektör olan Aldis lambası, ışığı kısa ve uzun süreli açıp kapatarak görsel Mors haberleşmesi yapılmasını sağlar.'),
  ('Mors kodunu ezberlemeyi kolaylaştırmak için kullanılan, yukarıdan aşağıya doğru sola gidildikçe "nokta", sağa gidildikçe "çizgi" eklenen görsel eğitim şemasına ne ad verilir?', 'İkili Mors ağacı', ['Fonetik kodlama piramidi', 'Altı noktalı kabartma matrisi', 'Semafor açısal çemberi'], 'Mors ikili ağacı, kök noktadan başlayıp her adımda nokta için sola, çizgi için sağa dallanarak harflerin hızlıca bulunmasını sağlar.'),
  ('Görme engellilerin okuyup yazabilmesi için geliştirilen 6 noktalı kabartma yazı sisteminin mucidi Louis Braille hangi ülkenin vatandaşıdır?', 'Fransa', ['Belçika', 'İsviçre', 'İngiltere'], '1809 yılında Paris yakınlarındaki Coupvray kasabasında doğan Louis Braille, kendi adıyla anılan kabartma alfabeyi Fransa\'da geliştirmiştir.'),
  ('Standart bir Braille hücresinde kabartma noktalar kaça kaçlık bir dikdörtgen dizilim (matris) oluşturacak şekilde yerleştirilmiştir?', 'Dikeyde 3, yatayda 2 nokta (toplam 6 nokta)', ['Dikeyde 2, yatayda 3 nokta (toplam 6 nokta)', 'Dikeyde 4, yatayda 2 nokta (toplam 8 nokta)', 'Dikeyde 3, yatayda 3 nokta (toplam 9 nokta)'], 'Klasik Braille hücresi, sol sütunda yukarıdan aşağıya 1-2-3 ve sağ sütunda 4-5-6 numaralı noktaların bulunduğu 3x2\'lik 6 noktadan oluşur.'),
  ('Louis Braille\'in doğum günü olan ve Birleşmiş Milletler tarafından görme engellilerin erişilebilirlik haklarına dikkat çekmek amacıyla ilan edilen "Dünya Braille Günü" hangi tarihte kutlanır?', '4 Ocak', ['15 Ekim', '3 Aralık', '23 Eylül'], 'Louis Braille 4 Ocak 1809\'da doğduğu için BM Genel Kurulu tarafından 4 Ocak tarihi Dünya Braille Günü olarak kabul edilmiştir.'),
  ('Çocuk yaşta babasının saraç (deri işçiliği) atölyesinde oynarken elindeki keskin biz aletinin gözüne batması sonucu oluşan enfeksiyonla görme yetisini kaybeden Louis Braille, eğitim gördüğü Paris\'teki Kraliyet Görme Engelli Gençler Enstitüsünü kim kurmuştur?', 'Valentin Haüy', ['Denis Diderot', 'Abbé de l\'Épée', 'Jean-Jacques Rousseau'], 'Valentin Haüy, 1784 yılında Paris\'te dünyadaki ilk görme engelliler okulunu kurmuş ve kabartılmış normal Latin harfleriyle okuma denemeleri yapmıştır.'),
  ('İlaç kutularının, asansör düğmelerinin ve kağıt paraların üzerindeki kabartma işaretlerin erişilebilirlik açısından temel işlevi nedir?', 'Görme engelli bireylerin başkasına bağımlı kalmadan güvenli ve bağımsız biçimde bilgiye erişmesini sağlamak', ['Ambalajların üretim bandında optik barkod okuyucular tarafından daha hızlı taranmasını sağlamak', 'Karanlık ortamlarda çalışan gören personelin renkleri ayırt etmesine yardımcı olmak', 'Kağıt ve karton yüzeylerin nemden etkilenerek yıpranmasını fiziksel olarak geciktirmek'], 'Evrensel tasarım ilkeleri gereği ilaç kutularında Braille bulunması, görme engellilerin yanlış ilaç kullanma riskini ortadan kaldırarak bağımsız yaşamı destekler.'),
  ('İşaret dilleri hakkında toplumda sıkça karşılaşılan aşağıdaki düşüncelerden hangisi dilbilimsel olarak DOĞRUDUR?', 'Dünyada tek bir evrensel işaret dili yoktur; Türk İşaret Dili (TİD) ve Amerikan İşaret Dili (ASL) gibi her toplumun kendine özgü doğal işaret dilleri vardır', ['İşaret dili, konuşulan dillerin kelimelerinin yalnızca parmaklarla harf harf kodlanmasından ibaret yapay bir sistemdir', 'Bütün ülkelerdeki sağır bireyler Birleşmiş Milletler tarafından hazırlanan tek ve ortak bir işaret diliyle anlaşırlar', 'İşaret dillerinin kendine ait bir dilbilgisi veya sözdizimi kuralı bulunmaz, yalnızca pandomim hareketlerinden oluşur'], 'İşaret dilleri konuşma dillerinden bağımsız gelişen, kendilerine özgü fonolojisi, morfolojisi ve sözdizimi olan tam teşekküllü doğal dillerdir ve ülkeden ülkeye değişir.'),
  ('Hem sağır kültürünün hem de işaret diliyle yükseköğretimin dünyadaki en önemli merkezi kabul edilen, tüm derslerin ve kampüs yaşamının işaret diliyle yürütüldüğü Washington D.C.\'deki Gallaudet Üniversitesi hangi ülkededir?', 'Amerika Birleşik Devletleri', ['Kanada', 'Birleşik Krallık', 'Fransa'], '1864 yılında Başkan Abraham Lincoln\'ün onayladığı yasayla kurulan Gallaudet Üniversitesi, sağır ve işitme güçlüğü çeken öğrenciler için tasarlanmış dünyadaki ilk ve tek sosyal bilimler üniversitesidir.'),
  ('İşaret dilinde elin yalnızca şekli değil, avuç içinin hangi yöne baktığı da (yukarı, aşağı, karşıya veya vücuda doğru) kelimenin anlamını tamamen değiştirebilir; bu özellik dilbilimde hangi kavramla adlandırılır?', 'El yönelimi (Oryantasyon)', ['Parmak hecelemesi (Daktiloloji)', 'Dudak senkronizasyonu', 'Akustik rezonans'], 'Beş temel parametreden biri olan yönelim (orientation), aynı el şekli ve konumda avuç içinin baktığı yön değiştiğinde farklı bir sözcük oluşmasını sağlar.'),
  ('Televizyon yayınlarında, acil durum duyurularında ve kamu toplantılarında ekranın bir köşesinde yer alarak konuşulanları eşzamanlı olarak işaret diline aktaran uzmana ne ad verilir?', 'İşaret dili tercümanı', ['Stenografi operatörü', 'Fonetik diksiyon eğitmeni', 'Ses betimleme yazarı'], 'Konuşma dili ile işaret dili arasında çift yönlü ve eşzamanlı çeviri yapan profesyonellere işaret dili tercümanı denir.'),
  ('Uluslararası Mors alfabesinde üç kısa darbe (...) ile gösterilen harf hangisidir?', 'S', ['O', 'H', 'U'], 'SOS sinyalinin başındaki ve sonundaki S harfi üç adet kısa sinyalden (nokta) oluşur.'),
  ('Braille alfabesiyle basılmış bir metni okuyan görme engelli birey vücudunun hangi kısmındaki dokunma reseptörlerini aktif olarak kullanır?', 'İşaret parmaklarının uç kısımlarını', ['Avuç içinin tam orta bölgesini', 'El bileğinin dış yüzeyini', 'Başparmağın tırnak kenarını'], 'İnsan vücudunda mekanoreseptör yoğunluğunun en yüksek olduğu bölgelerden biri işaret parmağı uçlarıdır; usta Braille okuyucuları iki elin işaret parmaklarını birlikte kullanır.'),
  ('İşitme engelli ve sağır bireylerin görsel iletişimine dikkat çekmek için evlerde kapı zili veya yangın alarmı çaldığında ses yerine hangi uyarı düzeneği kullanılır?', 'Çakarlı (yanıp sönen) güçlü flaş ışığı veya yastık altı titreşim aparatı', ['Daha yüksek desibelli ultrasonik siren hoparlörü', 'Odaya koku yayan otomatik basınçlı sprey sistemi', 'Duvarlara yerleştirilen kabartma Braille uyarı levhası'], 'Erişilebilir yaşam alanlarında işitsel alarmlar, çakarlı flaş lambaları ve yatak/bileklik titreşim modülleriyle görsel ve dokunsal uyarılara dönüştürülür.'),
  ('Görme engellilerin akıllı telefon ve bilgisayarları kabartma ekran olmadan da kullanabilmesini sağlayan, ekrandaki metinleri ve düğmeleri yüksek hızda sentetik sese dönüştüren yazılımlara ne ad verilir?', 'Ekran okuyucu', ['Optik karakter tarayıcı', 'Sesli komut dikte edici', 'Grafik çözünürlük artırıcı'], 'NVDA, JAWS, VoiceOver ve TalkBack gibi ekran okuyucu yazılımlar, arayüz öğelerini sese (veya bağlıysa Braille ekrana) aktararak dijital erişilebilirlik sağlar.'),
  ('NATO ve Uluslararası Sivil Havacılık Örgütü (ICAO) tarafından kullanılan fonetik alfabenin ilk üç harfi (A, B, C) sırasıyla hangi kod kelimelerle ifade edilir?', 'Alfa, Bravo, Charlie', ['Alfa, Beta, Ceyhan', 'Amerika, Bükreş, Cenevre', 'Atlas, Bora, Cihan'], 'Uluslararası telsiz haberleşmesinde A, B ve C harfleri karışıklığı önlemek için Alfa, Bravo ve Charlie kelimeleriyle kodlanır.'),
  ('Havacılık, denizcilik ve acil durum telsiz görüşmelerinde "B" ve "P" ya da "M" ve "N" gibi sesçe birbirine benzeyen harflerin tek tek söylenmesi yerine NATO fonetik alfabesinin kullanılmasının temel amacı nedir?', 'Telsiz paraziti, düşük ses kalitesi ve farklı aksanlar yüzünden oluşabilecek yanlış anlaşılmaları ortadan kaldırmak', ['Mesajların içeriğini üçüncü şahıslardan gizleyerek askeri şifreleme güvenliği sağlamak', 'Telsiz frekanslarının harcadığı elektrik gücünü azaltarak batarya ömrünü iki katına çıkarmak', 'Pilotların ve gemi kaptanlarının yabancı dil öğrenme zorunluluğunu tamamen ortadan kaldırmak'], 'Heceleme (fonetik) alfabesi bir şifreleme yöntemi değildir; aksine parazitli hatlarda her harfin net ve tek anlamlı anlaşılmasını sağlayan açık bir güvenlik standardıdır.'),
  ('NATO fonetik alfabesinde "Z" harfini temsil eden kod kelime aşağıdakilerden hangisidir?', 'Zulu', ['Zebra', 'Zürih', 'Zorro'], 'NATO/ICAO fonetik alfabesinin son harfi olan Z, "Zulu" kelimesiyle kodlanır (havacılıkta UTC saat dilimi de Zulu saati olarak anılır).'),
  ('NATO fonetik alfabesinde dans isimlerinden seçilmiş olan "F" ve "T" harflerinin kod karşılıkları sırasıyla hangileridir?', 'Foxtrot ve Tango', ['Flamenko ve Twist', 'Fandango ve Tarantella', 'Vals ve Çarliston'], 'Uluslararası fonetik alfabede F harfi "Foxtrot", T harfi ise "Tango" dans adlarıyla temsil edilir.'),
  ('NATO fonetik alfabesinde takvimdeki aylardan seçilmiş olan tek kod kelime hangi harfi temsil eden "November" sözcüğüdür?', 'N', ['M', 'O', 'A'], 'İngilizcede Kasım ayı anlamına gelen "November", fonetik alfabede N harfinin karşılığıdır.'),
  ('Uluslararası denizcilik kurallarına göre seyir halindeki bir geminin geceleyin sancak (sağ) ve iskele (sol) bordalarında yakmak zorunda olduğu borda fenerlerinin renkleri sırasıyla nasıldır?', 'Sancak (sağ) taraf yeşil, iskele (sol) taraf kırmızı', ['Sancak (sağ) taraf kırmızı, iskele (sol) taraf yeşil', 'Sancak (sağ) taraf mavi, iskele (sol) taraf sarı', 'Sancak (sağ) taraf beyaz, iskele (sol) taraf turuncu'], 'Denizde Çatışmayı Önleme Tüzüğü (COLREG) uyarınca hem gemilerde hem uçaklarda sağ (sancak) kenar ışığı yeşil, sol (iskele) kenar ışığı kırmızıdır.'),
  ('Denizde ve havacılıkta sesli telsiz (radyotelefon) üzerinden yapılan en üst düzey hayati tehlike ve batma/düşme çağrısında üç kez üst üste söylenen uluslararası kelime hangisidir?', 'Mayday', ['Pan-Pan', 'Sécurité', 'Roger'], 'Fransızca "m\'aider" (bana yardım edin) ifadesinden türetilen "Mayday, Mayday, Mayday", can veya araç kaybına yol açabilecek yakın ve ciddi tehlikelerde kullanılan en üst acil çağrıdır.'),
  ('Denizcilikte iki gemi görüş mesafesindeyken bir denizcinin iki elinde tuttuğu renkli kare bayrakları vücudunun etrafında saat kadranı gibi farklı açılarda (45 derecelik dilimlerle) tutarak harfleri kodladığı görsel iletişim sistemine ne ad verilir?', 'Semafor', ['Aldis projektör telgrafı', 'Altı noktalı kabartma dizgesi', 'Uluslararası flama donanımı'], 'Semafor sisteminde her harf, sağ ve sol koldaki bayrakların sekiz ana açısal pozisyonda oluşturduğu geometrik kombinasyonlarla karşı gemiye gösterilir.'),
  ('Resmi bayramlarda, liman törenlerinde veya geminin denize indiriliş günlerinde bir geminin pruvasından (başından) direk tepelerine ve pupasına (kıçına) kadar tüm uluslararası işaret bayraklarının ipe dizilerek çekilmesi geleneğine denizcilikte ne ad verilir?', 'Gemiyi donatmak', ['Sancak yarıya indirmek', 'Karantina flaması basmak', 'Borda iskelesi sürmek'], 'Tören ve kutlama günlerinde gemilerin tüm kod bayraklarıyla baştan kıça kadar rengarenk süslenmesine denizcilik terminolojisinde "alay sancaklarıyla donatma" (dressing overall) denir.'),
  ('Telsiz haberleşmesinde mesajı alan operatörün kullandığı "Roger" ifadesi iletişim prosedürlerinde tam olarak hangi anlama gelir?', 'Son gönderdiğiniz mesajın tamamını aldım ve anladım', ['Verdiğiniz emri onaylıyor ve yerine getireceğime söz veriyorum', 'Lütfen son söylediğiniz cümleyi daha yavaş tekrarlayın', 'Telsiz kanalını kapatıyorum ve nöbetten ayrılıyorum'], '"Roger" kelimesi, NATO öncesi eski fonetik alfabede "Received" (Alındı) kelimesinin baş harfi olan R\'nin karşılığıydı; "Mesajınız alındı" demektir, "Emri uygulayacağım" anlamındaki "Wilco" (Will comply) ile karıştırılmamalıdır.'),
  ('Tüplü dalış (SCUBA) yapan dalgıçların su altında konuşamadıkları için kullandıkları uluslararası el işaretlerinde, başparmak ve işaret parmağını birleştirerek yapılan "OK" (Tamam/İyiyim) işareti yerine yanlışlıkla "başparmağın yukarı kaldırılması" su altında ne anlama gelir?', 'Yukarı çıkalım / Dalışı sonlandırıp yüzeye yükseliyorum', ['Her şey yolunda / Hava tüpüm tamamen dolu', 'Diğer dalgıçları burada bekleyelim / Derinliği koruyalım', 'Fotoğraf çekiyorum / Lütfen sabit durup gülümseyin'], 'Karadaki günlük yaşamda "harika/tamam" anlamına gelen yukarı kalkık başparmak, dalış iletişiminde yön belirtir ve "Yüzeye çıkıyoruz" demektir; "İyiyim" demek için mutlaka başparmak ve işaret parmağıyla halka (OK) yapılır.'),
  ('Geceleyin gökyüzünde uçan bir yolcu uçağının sol kanat ucunda kırmızı, sağ kanat ucunda yeşil ve kuyruk kısmında beyaz seyrüsefer (navigasyon) ışıkları bulunmasının kökeni hangi ulaşım alanındaki kurallara dayanır?', 'Uluslararası denizcilik borda ve pupa feneri kurallarına', ['Buharlı demiryolu lokomotiflerinin istasyon ışıklarına', 'Atlı posta arabalarının şehir içi trafik lambalarına', 'Orta Çağ kalelerinin meşale nöbet dizilimlerine'], 'Havacılık navigasyon ışıkları doğrudan denizcilikten uyarlanmıştır: Sol (iskele) kırmızı, sağ (sancak) yeşil ve arka (pupa/kuyruk) beyaz ışık sayesinde geceleyin iki pilot birbirlerinin uçuş yönünü anında anlar.'),
  ('Birleşmiş Milletler Engellilerin Haklarına İlişkin Sözleşme\'de (BM EHİS) Braille yazısı, dokunsal iletişim, iri puntolu yazı, erişilebilir multimedya ve işaret dilleri hangi temel hak kapsamında güvence altına alınmıştır?', 'İfade ve düşünce özgürlüğü ile bilgiye erişim hakkı', ['Yalnızca uluslararası gümrük vergisi muafiyeti hakkı', 'Diplomatik pasaportla vizesiz seyahat etme ayrıcalığı', 'Askeri telsiz frekanslarını ticari amaçla kiralama hakkı'], 'BM Engelli Hakları Sözleşmesi\'nin 2. ve 21. maddeleri; işaret dillerini, Braille alfabesini ve tüm alternatif-destekleyici iletişim biçimlerini resmi etkileşim ve bilgiye erişim hakkının ayrılmaz parçası sayar.'),
  ('NATO fonetik alfabesinde "K" harfini temsil eden ve uluslararası ağırlık biriminin kısaltmasından gelen kod kelime hangisidir?', 'Kilo', ['Karat', 'Kantar', 'Kuvvet'], 'Uluslararası telsiz heceleme alfabesinde K harfi, neredeyse tüm dünya dillerinde bilinen "Kilo" kelimesiyle kodlanır.'),
  ('NATO fonetik alfabesinde "C" harfi "Charlie" ile gösterilirken, Türkiye\'de günlük telefon görüşmelerinde ve ulusal kurumlarda kullanılan Türkçe kodlama (heceleme) alfabesinde "C" ve "Ç" harfleri geleneksel olarak hangi şehir adlarıyla kodlanır?', 'Ceyhan ve Çanakkale', ['Cizre ve Çorum', 'Cide ve Çankırı', 'Cihanbeyli ve Çeşme'], 'Uluslararası havacılık ve denizcilikte NATO alfabesi kullanılırken, Türkiye içi Türkçe telefon/telsiz hecelemesinde PTT geleneğinden bu yana il ve ilçe adları (Adana, Bolu, Ceyhan, Çanakkale...) kullanılır.'),
  ('Beyaz baston kullanan bir kişinin caddede yürürken bastonunun alt kısmında kırmızı şeritler bulunması uluslararası erişilebilirlik sembollerinde neyi ifade eder?', 'Kişinin hem görme hem de işitme engelli (sağır-kör / deafblind) olduğunu', ['Bastonun belediye tarafından geçici olarak ödünç verildiğini', 'Kişinin yalnızca gece karanlığında görme güçlüğü yaşadığını', 'Bastonun içinde elektronik sesli navigasyon cihazı bulunduğunu'], 'Düz beyaz baston görme engelli bireyleri temsil ederken, beyaz zemin üzerinde kırmızı yatay bantlar bulunan baston kullanıcının hem görme hem işitme kaybı yaşadığını çevredekilere ve sürücülere bildirir.'),
];
